@Component("fundsTransfer-handler")
@ProcessingGroup("fundsTransfer-processing-group")
public class FundsTransferEventHandler {
	
	// core constructor
	FundsTransferEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateFundsTransferEvent
     */
    @EventHandler
    public void handle( CreateFundsTransferEvent event) {
        entityManager.persist(new FundsTransfer(event.getFundsTransferId(), event.getTransferReference(), event.getAmount(), event.getRequestedDate(), event.getExecutionDate(), event.getPurpose(), event.getFeeAmount(), event.getSourceAccount(), event.getDestinationAccount(), event.getExternalBeneficiary(), event.getInitiatedBy(), event.getTransactions(), event.getMethod(), event.getStatus()));
    }

    /*
     * @param	event UpdateFundsTransferEvent
     */
    @EventHandler
    public FundsTransfer handle( UpdateFundsTransferEvent event) {
    	entityManager.merge(new FundsTransfer(event.getFundsTransferId(), event.getTransferReference(), event.getAmount(), event.getRequestedDate(), event.getExecutionDate(), event.getPurpose(), event.getFeeAmount(), event.getSourceAccount(), event.getDestinationAccount(), event.getExternalBeneficiary(), event.getInitiatedBy(), event.getTransactions(), event.getMethod(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteFundsTransferEvent
     */
    @EventHandler
    public void on( DeleteFundsTransferEvent event) {
    	FundsTransfer entity = new FundsTransfer();
   
    	// ------------------------------------------
    	// apply the FundsTransferId
    	// ------------------------------------------
    	entity.setFundsTransferId( event.getFundsTransferId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final FundsTransferRepository fundsTransferEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(FundsTransferEventHandler.class.getName());

}
